  1→import { patchState, signalStore, withMethods, withState } from "@ngrx/signals";
  2→import type {
  3→  ScenarioContent,
  4→  ScenarioEventDef,
  5→  ScenarioIssueDef,
  6→  DecisionTemplateDef,
  7→} from "../../core/scenario-api.service";
  8→
  9→interface ScenarioBuilderState {
 10→  scenarioId: number | null;
 11→  title: string;
 12→  description: string;
 13→  content: ScenarioContent;
 14→  saving: boolean;
 15→  error: string | null;
 16→}
 17→
 18→const emptyContent: ScenarioContent = {
 19→  phases: [],
 20→  events: [],
 21→  issues: [],
 22→  decision_templates: [],
 23→  default_time_factor: 1.0,
 24→  briefing: "",
 25→  objectives: [],
 26→  rules: [],
 27→  roles: [],
 28→  game_mode: "classic",
 29→};
 30→
 31→export const ScenarioBuilderStore = signalStore(
 32→  withState<ScenarioBuilderState>({
 33→    scenarioId: null,
 34→    title: "",
 35→    description: "",
 36→    content: emptyContent,
 37→    saving: false,
 38→    error: null,
 39→  }),
 40→
 41→  withMethods((store) => ({
 42→    loadScenario(
 43→      id: number,
 44→      title: string,
 45→      description: string,
 46→      content: ScenarioContent | null,
 47→    ): void {
 48→      patchState(store, {
 49→        scenarioId: id,
 50→        title,
 51→        description,
 52→        content: content ?? emptyContent,
 53→      });
 54→    },
 55→
 56→    setTitle(title: string): void {
 57→      patchState(store, { title });
 58→    },
 59→
 60→    setDescription(description: string): void {
 61→      patchState(store, { description });
 62→    },
 63→
 64→    setTimeFactor(factor: number): void {
 65→      patchState(store, {
 66→        content: { ...store.content(), default_time_factor: factor },
 67→      });
 68→    },
 69→
 70→    addEvent(event: ScenarioEventDef): void {
 71→      patchState(store, {
 72→        content: {
 73→          ...store.content(),
 74→          events: [...store.content().events, event],
 75→        },
 76→      });
 77→    },
 78→
 79→    removeEvent(eventId: string): void {
 80→      patchState(store, {
 81→        content: {
 82→          ...store.content(),
 83→          events: store.content().events.filter((e) => e.id !== eventId),
 84→        },
 85→      });
 86→    },
 87→
 88→    updateEvent(eventId: string, updates: Partial<ScenarioEventDef>): void {
 89→      patchState(store, {
 90→        content: {
 91→          ...store.content(),
 92→          events: store
 93→            .content()
 94→            .events.map((e) => (e.id === eventId ? { ...e, ...updates } : e)),
 95→        },
 96→      });
 97→    },
 98→
 99→    addIssue(issue: ScenarioIssueDef): void {
100→      patchState(store, {
101→        content: {
102→          ...store.content(),
103→          issues: [...store.content().issues, issue],
104→        },
105→      });
106→    },
107→
108→    removeIssue(issueId: string): void {
109→      patchState(store, {
110→        content: {
111→          ...store.content(),
112→          issues: store.content().issues.filter((i) => i.id !== issueId),
113→        },
114→      });
115→    },
116→
117→    updateIssue(issueId: string, updates: Partial<ScenarioIssueDef>): void {
118→      patchState(store, {
119→        content: {
120→          ...store.content(),
121→          issues: store
122→            .content()
123→            .issues.map((i) => (i.id === issueId ? { ...i, ...updates } : i)),
124→        },
125→      });
126→    },
127→
128→    addDecisionTemplate(template: DecisionTemplateDef): void {
129→      patchState(store, {
130→        content: {
131→          ...store.content(),
132→          decision_templates: [...store.content().decision_templates, template],
133→        },
134→      });
135→    },
136→
137→    removeDecisionTemplate(templateId: string): void {
138→      patchState(store, {
139→        content: {
140→          ...store.content(),
141→          decision_templates: store
142→            .content()
143→            .decision_templates.filter((d) => d.id !== templateId),
144→        },
145→      });
146→    },
147→
148→    updateDecisionTemplate(
149→      templateId: string,
150→      updates: Partial<DecisionTemplateDef>,
151→    ): void {
152→      patchState(store, {
153→        content: {
154→          ...store.content(),
155→          decision_templates: store
156→            .content()
157→            .decision_templates.map((d) =>
158→              d.id === templateId ? { ...d, ...updates } : d,
159→            ),
160→        },
161→      });
162→    },
163→
164→    setBriefing(briefing: string): void {
165→      patchState(store, {
166→        content: { ...store.content(), briefing },
167→      });
168→    },
169→
170→    setSaving(saving: boolean): void {
171→      patchState(store, { saving });
172→    },
173→
174→    setError(error: string): void {
175→      patchState(store, { error, saving: false });
176→    },
177→
178→    clearError(): void {
179→      patchState(store, { error: null });
180→    },
181→
182→    reset(): void {
183→      patchState(store, {
184→        scenarioId: null,
185→        title: "",
186→        description: "",
187→        content: emptyContent,
188→        saving: false,
189→        error: null,
190→      });
191→    },
192→  })),
193→);
