  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  inject,
  5→  OnInit,
  6→  signal,
  7→} from "@angular/core";
  8→import { FormsModule } from "@angular/forms";
  9→import {
 10→  PageHeaderComponent,
 11→  CardComponent,
 12→  ButtonDirective,
 13→  InputComponent,
 14→  BadgeComponent,
 15→  CollapsiblePanelComponent,
 16→} from "@aspect/ui";
 17→import { DomainService } from "../../core/domain.service";
 18→import { ScenarioApiService } from "../../core/scenario-api.service";
 19→import type { DecisionTemplateDef } from "../../core/scenario-api.service";
 20→import { ScenarioBuilderStore } from "./scenario-builder.store";
 21→import { ScenarioEventEditorComponent } from "./scenario-event-editor";
 22→import { ScenarioIssueEditorComponent } from "./scenario-issue-editor";
 23→import { validateScenarioContent } from "./validate-scenario-content";
 24→
 25→@Component({
 26→  selector: "tfc-scenario-builder-view",
 27→  changeDetection: ChangeDetectionStrategy.OnPush,
 28→  providers: [ScenarioBuilderStore],
 29→  imports: [
 30→    FormsModule,
 31→    PageHeaderComponent,
 32→    CardComponent,
 33→    ButtonDirective,
 34→    InputComponent,
 35→    BadgeComponent,
 36→    CollapsiblePanelComponent,
 37→    ScenarioEventEditorComponent,
 38→    ScenarioIssueEditorComponent,
 39→  ],
 40→  template: `
 41→    <div class="flex flex-col gap-md p-lg">
 42→      <ui-page-header title="Scenario Builder" />
 43→
 44→      <div class="flex gap-md">
 45→        <ui-input
 46→          id="scenario-title"
 47→          label="Title"
 48→          placeholder="Scenario title"
 49→          [value]="store.title()"
 50→          (valueChange)="store.setTitle($event)"
 51→        />
 52→        <ui-input
 53→          id="scenario-desc"
 54→          label="Description"
 55→          placeholder="Description"
 56→          [value]="store.description()"
 57→          (valueChange)="store.setDescription($event)"
 58→        />
 59→        <button uiButton variant="default" (click)="save()">
 60→          {{ store.scenarioId() ? "Update" : "Create" }}
 61→        </button>
 62→        @if (store.scenarioId()) {
 63→          <button uiButton variant="outline" (click)="store.reset()">
 64→            New
 65→          </button>
 66→        }
 67→      </div>
 68→
 69→      @if (store.error()) {
 70→        <div
 71→          class="p-sm border border-destructive bg-destructive/10 text-destructive text-sm rounded"
 72→          role="alert"
 73→        >
 74→          <strong>Validation errors:</strong>
 75→          <ul class="mt-xs ml-md list-disc">
 76→            @for (err of store.error()!.split("\\n"); track err) {
 77→              <li>{{ err }}</li>
 78→            }
 79→          </ul>
 80→        </div>
 81→      }
 82→
 83→      <div class="grid grid-cols-2 gap-md">
 84→        <tfc-scenario-event-editor />
 85→        <tfc-scenario-issue-editor />
 86→
 87→        <ui-card [title]="domain.term('decision') + ' Templates'">
 88→          @for (dt of store.content().decision_templates; track dt.id) {
 89→            <div class="flex flex-col gap-xs p-sm border-b">
 90→              @if (editingDtId() === dt.id) {
 91→                <div class="flex flex-col gap-xs">
 92→                  <ui-input
 93→                    id="edit-dt-title"
 94→                    label="Title"
 95→                    [value]="editDtTitle()"
 96→                    (valueChange)="editDtTitle.set($event)"
 97→                  />
 98→                  <ui-input
 99→                    id="edit-dt-desc"
100→                    label="Description"
101→                    [value]="editDtDesc()"
102→                    (valueChange)="editDtDesc.set($event)"
103→                  />
104→                  <div class="flex gap-sm">
105→                    <ui-input
106→                      id="edit-dt-issue"
107→                      label="Issue ID"
108→                      [value]="editDtIssueId()"
109→                      (valueChange)="editDtIssueId.set($event)"
110→                    />
111→                    <div class="flex flex-col gap-xs" style="flex:1">
112→                      <label class="text-xs">Question Type</label>
113→                      <select
114→                        class="input-base"
115→                        [value]="editDtQType()"
116→                        (change)="editDtQType.set(sel($event))"
117→                      >
118→                        <option value="single_choice">Single Choice</option>
119→                        <option value="multi_choice">Multi Choice</option>
120→                        <option value="free_text">Free Text</option>
121→                      </select>
122→                    </div>
123→                  </div>
124→                  <div class="flex gap-sm">
125→                    <button
126→                      uiButton
127→                      variant="default"
128→                      size="sm"
129→                      (click)="saveDt(dt.id)"
130→                    >
131→                      Save
132→                    </button>
133→                    <button
134→                      uiButton
135→                      variant="outline"
136→                      size="sm"
137→                      (click)="editingDtId.set(null)"
138→                    >
139→                      Cancel
140→                    </button>
141→                  </div>
142→                </div>
143→              } @else {
144→                <div class="flex items-center justify-between">
145→                  <div>
146→                    <span class="text-sm font-medium">{{ dt.title }}</span>
147→                    <ui-badge variant="secondary">{{
148→                      dt.question_type
149→                    }}</ui-badge>
150→                    <span class="text-xs text-muted-foreground ml-sm"
151→                      >issue: {{ dt.issue_id }}</span
152→                    >
153→                  </div>
154→                  <div class="flex gap-xs">
155→                    <button
156→                      uiButton
157→                      variant="outline"
158→                      size="sm"
159→                      (click)="editDt(dt)"
160→                    >
161→                      Edit
162→                    </button>
163→                    <button
164→                      uiButton
165→                      variant="destructive"
166→                      size="sm"
167→                      (click)="store.removeDecisionTemplate(dt.id)"
168→                    >
169→                      Remove
170→                    </button>
171→                  </div>
172→                </div>
173→              }
174→            </div>
175→          } @empty {
176→            <p class="text-muted-foreground text-sm p-sm">
177→              No decision templates yet.
178→            </p>
179→          }
180→          <div class="flex gap-sm p-sm border-t">
181→            <ui-input
182→              id="dt-title"
183→              label=""
184→              placeholder="Decision title"
185→              [(value)]="newDtTitle"
186→            />
187→            <ui-input
188→              id="dt-issue"
189→              label=""
190→              placeholder="Issue ID"
191→              [(value)]="newDtIssueId"
192→            />
193→            <button uiButton variant="outline" size="sm" (click)="addDt()">
194→              Add
195→            </button>
196→          </div>
197→        </ui-card>
198→
199→        <ui-card title="Settings">
200→          <div class="flex flex-col gap-sm p-sm">
201→            <div class="flex items-center gap-sm">
202→              <span class="text-sm">Default Time Factor:</span>
203→              <input
204→                type="number"
205→                class="input-base"
206→                style="width: var(--container-xs, 5rem)"
207→                [value]="store.content().default_time_factor"
208→                (change)="onTimeFactorChange($event)"
209→              />
210→            </div>
211→            <div class="flex flex-col gap-xs">
212→              <span class="text-sm">Briefing:</span>
213→              <textarea
214→                class="input-base"
215→                rows="3"
216→                [value]="store.content().briefing ?? ''"
217→                (input)="onBriefingChange($event)"
218→              ></textarea>
219→            </div>
220→          </div>
221→        </ui-card>
222→      </div>
223→
224→      <ui-collapsible-panel>
225→        <span panelTitle>Existing Scenarios</span>
226→        @for (s of scenarios(); track s.id) {
227→          <div class="flex items-center justify-between p-sm border-b">
228→            <span
229→              class="text-sm font-medium cursor-pointer"
230→              (click)="loadScenario(s.id)"
231→            >
232→              {{ s.title }}
233→            </span>
234→            <button
235→              uiButton
236→              variant="destructive"
237→              size="sm"
238→              (click)="deleteScenario(s.id)"
239→            >
240→              Delete
241→            </button>
242→          </div>
243→        } @empty {
244→          <p class="text-muted-foreground text-sm p-sm">No scenarios found.</p>
245→        }
246→      </ui-collapsible-panel>
247→    </div>
248→  `,
249→})
250→export class ScenarioBuilderView implements OnInit {
251→  protected readonly store = inject(ScenarioBuilderStore);
252→  protected readonly domain = inject(DomainService);
253→  private readonly api = inject(ScenarioApiService);
254→  protected readonly scenarios = signal<{ id: number; title: string }[]>([]);
255→  private counter = 0;
256→
257→  protected readonly newDtTitle = signal("");
258→  protected readonly newDtIssueId = signal("");
259→  protected readonly editingDtId = signal<string | null>(null);
260→  protected readonly editDtTitle = signal("");
261→  protected readonly editDtDesc = signal("");
262→  protected readonly editDtIssueId = signal("");
263→  protected readonly editDtQType = signal("single_choice");
264→
265→  ngOnInit(): void {
266→    this.loadList();
267→  }
268→
269→  protected sel(event: Event): string {
270→    const target = event.target;
271→    if (target instanceof HTMLSelectElement) return target.value;
272→    return "";
273→  }
274→
275→  private loadList(): void {
276→    this.api.list().subscribe({
277→      next: (list) =>
278→        this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
279→    });
280→  }
281→
282→  protected loadScenario(id: number): void {
283→    this.api.get(id).subscribe({
284→      next: (s) =>
285→        this.store.loadScenario(s.id, s.title, s.description, s.content),
286→    });
287→  }
288→
289→  protected save(): void {
290→    this.store.clearError();
291→    const content = this.store.content();
292→    const errors = validateScenarioContent(content);
293→    if (!this.store.title().trim()) {
294→      errors.unshift("Title is required.");
295→    }
296→    if (errors.length > 0) {
297→      this.store.setError(errors.join("\n"));
298→      return;
299→    }
300→    this.store.setSaving(true);
301→    const payload = {
302→      title: this.store.title(),
303→      description: this.store.description(),
304→      content,
305→    };
306→    const id = this.store.scenarioId();
307→    const req = id ? this.api.update(id, payload) : this.api.create(payload);
308→    req.subscribe({
309→      next: (s) => {
310→        this.store.loadScenario(s.id, s.title, s.description, s.content);
311→        this.store.setSaving(false);
312→        this.loadList();
313→      },
314→      error: () =>
315→        this.store.setError("Save failed — server rejected the scenario."),
316→    });
317→  }
318→
319→  protected deleteScenario(id: number): void {
320→    this.api.delete(id).subscribe({ next: () => this.loadList() });
321→  }
322→
323→  protected addDt(): void {
324→    const title = this.newDtTitle().trim();
325→    const issueId = this.newDtIssueId().trim();
326→    if (!title || !issueId) return;
327→    this.store.addDecisionTemplate({
328→      id: `dt-${++this.counter}`,
329→      title,
330→      description: "",
331→      issue_id: issueId,
332→      question_type: "single_choice",
333→      options: [],
334→      completion_mode: "first_response",
335→    });
336→    this.newDtTitle.set("");
337→    this.newDtIssueId.set("");
338→  }
339→
340→  protected editDt(dt: DecisionTemplateDef): void {
341→    this.editingDtId.set(dt.id);
342→    this.editDtTitle.set(dt.title);
343→    this.editDtDesc.set(dt.description);
344→    this.editDtIssueId.set(dt.issue_id);
345→    this.editDtQType.set(dt.question_type);
346→  }
347→
348→  protected saveDt(dtId: string): void {
349→    this.store.updateDecisionTemplate(dtId, {
350→      title: this.editDtTitle(),
351→      description: this.editDtDesc(),
352→      issue_id: this.editDtIssueId(),
353→      question_type: this.editDtQType(),
354→    });
355→    this.editingDtId.set(null);
356→  }
357→
358→  protected onTimeFactorChange(event: Event): void {
359→    const target = event.target;
360→    if (!(target instanceof HTMLInputElement)) return;
361→    const val = parseFloat(target.value);
362→    if (val > 0) this.store.setTimeFactor(val);
363→  }
364→
365→  protected onBriefingChange(event: Event): void {
366→    const target = event.target;
367→    if (target instanceof HTMLTextAreaElement) {
368→      this.store.setBriefing(target.value);
369→    }
370→  }
371→}
