  1→import { Injectable, inject } from "@angular/core";
  2→import { HttpClient } from "@angular/common/http";
  3→import { Observable } from "rxjs";
  4→import { environment } from "./environment";
  5→import type { DecisionOption } from "./decision-api.service";
  6→
  7→export interface ScenarioEventDef {
  8→  id: string;
  9→  title: string;
 10→  description: string;
 11→  event_type: string;
 12→  scheduled_pt_ms: number;
 13→  duration_ms: number | null;
 14→  dependencies: string[];
 15→  triggered_issues: string[];
 16→  target_roles: string[];
 17→  role_descriptions: Record<string, string>;
 18→}
 19→
 20→export interface ScenarioIssueDef {
 21→  id: string;
 22→  title: string;
 23→  description: string;
 24→  trigger_mode: string;
 25→  trigger_time_pt_ms: number | null;
 26→  trigger_event_id: string | null;
 27→  auto_resolve_ms: number;
 28→}
 29→
 30→export interface DecisionTemplateDef {
 31→  id: string;
 32→  title: string;
 33→  description: string;
 34→  issue_id: string;
 35→  question_type: string;
 36→  options: DecisionOption[];
 37→  completion_mode: string;
 38→  timeout_ms?: number;
 39→  target_roles?: string[];
 40→  forced_option_ids?: string[];
 41→}
 42→
 43→export interface RoleDef {
 44→  id: string;
 45→  label: string;
 46→  player_type: string;
 47→}
 48→
 49→export interface ScenarioContent {
 50→  phases: {
 51→    id: string;
 52→    title: string;
 53→    description: string;
 54→    duration_ms: number | null;
 55→    events: string[];
 56→  }[];
 57→  events: ScenarioEventDef[];
 58→  issues: ScenarioIssueDef[];
 59→  decision_templates: DecisionTemplateDef[];
 60→  default_time_factor: number;
 61→  game_mode?: string;
 62→  briefing?: string;
 63→  objectives?: string[];
 64→  rules?: string[];
 65→  roles?: RoleDef[];
 66→}
 67→
 68→export interface ScenarioResponse {
 69→  id: number;
 70→  title: string;
 71→  description: string;
 72→  domain_id: number | null;
 73→  content: ScenarioContent | null;
 74→  version: number;
 75→  created_at: string;
 76→  updated_at: string;
 77→}
 78→
 79→export interface CreateScenarioRequest {
 80→  title: string;
 81→  description?: string;
 82→  domain_id?: number | null;
 83→  content?: ScenarioContent | null;
 84→}
 85→
 86→@Injectable({ providedIn: "root" })
 87→export class ScenarioApiService {
 88→  private readonly http = inject(HttpClient);
 89→  private readonly base = environment.apiBaseUrl;
 90→
 91→  list(): Observable<ScenarioResponse[]> {
 92→    return this.http.get<ScenarioResponse[]>(`${this.base}/api/scenarios`);
 93→  }
 94→
 95→  get(id: number): Observable<ScenarioResponse> {
 96→    return this.http.get<ScenarioResponse>(`${this.base}/api/scenarios/${id}`);
 97→  }
 98→
 99→  create(request: CreateScenarioRequest): Observable<ScenarioResponse> {
100→    return this.http.post<ScenarioResponse>(
101→      `${this.base}/api/scenarios`,
102→      request,
103→    );
104→  }
105→
106→  update(
107→    id: number,
108→    request: Partial<CreateScenarioRequest>,
109→  ): Observable<ScenarioResponse> {
110→    return this.http.put<ScenarioResponse>(
111→      `${this.base}/api/scenarios/${id}`,
112→      request,
113→    );
114→  }
115→
116→  delete(id: number): Observable<void> {
117→    return this.http.delete<void>(`${this.base}/api/scenarios/${id}`);
118→  }
119→}
