 9→export function validateScenarioContent(content: ScenarioContent): string[] {
10→  const errors: string[] = [];
11→
12→  const roles = content.roles ?? [];
13→  if (roles.length === 0) {
14→    errors.push("Scenario must define at least one role.");
15→  }
16→
17→  const playerTypes = new Set(roles.map((r) => r.player_type));
18→  if (roles.length > 0 && !playerTypes.has("decision_maker")) {
19→    errors.push("At least one role must have player_type 'decision_maker'.");
20→  }
21→
22→  const roleIds = new Set(roles.map((r) => r.id));
23→  for (const dt of content.decision_templates) {
24→    for (const rid of dt.target_roles ?? []) {
25→      if (!roleIds.has(rid)) {
26→        errors.push(
27→          `Decision template '${dt.id}' targets unknown role '${rid}'.`,
28→        );
29→      }
30→    }
31→  }
32→
33→  return errors;
