  if (typeof obj["title"] !== "string") return null;
  if (typeof obj["content"] !== "object" || obj["content"] === null) return null;
  return {
    title: obj["title"],
    description: typeof obj["description"] === "string" ? obj["description"] : "",
    content: obj["content"] as ScenarioContent,
  };
}
