1083→  template: `
1084→    @if (sortedEvents().length === 0) {
1085→      <div class="flex items-center justify-center p-2xl">
1086→        <p class="text-muted-foreground">No events to walk through.</p>
1087→      </div>
1088→    } @else {
1089→      <div class="flex flex-col items-center gap-lg p-lg" style="max-width: 40rem; margin: 0 auto">
1090→        @let event = sortedEvents()[safeIndex()];
1091→        <ui-card [title]="event.title" style="width: 100%">
1092→          <div class="flex flex-col gap-sm p-sm">
1093→            <div class="flex gap-sm items-center">
1094→              <ui-badge variant="secondary">{{ event.event_type }}</ui-badge>
1095→              <span class="text-sm text-muted-foreground">{{ formatTime(event.scheduled_pt_ms) }}</span>
1096→              @if (event.duration_ms) {
1097→                <span class="text-xs text-muted-foreground">duration: {{ formatTime(event.duration_ms) }}</span>
1098→              }
1099→            </div>
1100→            @if (event.description) {
1101→              <p class="text-sm">{{ event.description }}</p>
1102→            }
1103→            @if (event.target_roles.length > 0) {
1104→              <div class="flex gap-xs items-center">
1105→                <span class="text-xs text-muted-foreground">Roles:</span>
1106→                @for (role of event.target_roles; track role) {
1107→                  <ui-badge variant="outline">{{ role }}</ui-badge>
1108→                }
1109→              </div>
1110→            }
1111→            @if (event.triggered_issues.length > 0) {
1112→              <div class="flex gap-xs items-center">
1113→                <span class="text-xs text-muted-foreground">Triggers:</span>
1114→                @for (issueId of event.triggered_issues; track issueId) {
1115→                  <ui-badge variant="outline">{{ issueId }}</ui-badge>
1116→                }
1117→              </div>
1118→            }
1119→          </div>
1120→        </ui-card>
1121→
1122→        <div class="flex items-center gap-md">
1123→          <button
1124→            uiButton
1125→            variant="outline"
1126→            [disabled]="safeIndex() === 0"
1127→            (click)="currentIndex.set(safeIndex() - 1)"
1128→          >Previous</button>
1129→          <span class="text-sm text-muted-foreground">
1130→            Event {{ safeIndex() + 1 }} of {{ sortedEvents().length }}
1131→            — {{ formatTime(event.scheduled_pt_ms) }}
1132→          </span>
1133→          <button
1134→            uiButton
1135→            variant="outline"
1136→            [disabled]="safeIndex() >= sortedEvents().length - 1"
1137→            (click)="currentIndex.set(safeIndex() + 1)"
1138→          >Next</button>
1139→        </div>
1140→      </div>
1141→    }
1142→  `,
1143→})
1144→export class ScenarioWalkthroughComponent {
1145→  private readonly store = inject(ScenarioBuilderStore);
1146→
1147→  protected readonly sortedEvents = computed(() =>
1148→    [...this.store.content().events].sort(
1149→      (a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms,
1150→    ),
1151→  );
1152→
1153→  protected readonly currentIndex = signal(0);
1154→
1155→  /** Clamp index to valid range when events change */
1156→  protected readonly safeIndex = computed(() => {
1157→    const len = this.sortedEvents().length;
1158→    if (len === 0) return 0;
1159→    return Math.min(this.currentIndex(), len - 1);
1160→  });
