1484→  protected readonly isDirty = computed(() => {
1485→    const snap = this.store.loadedSnapshot();
1486→    if (!snap) return false;
1487→    const current = JSON.stringify({
1488→      title: this.store.title(),
1489→      description: this.store.description(),
1490→      content: this.store.content(),
1491→    });
1492→    return current !== snap;
1493→  });
1494→
1495→  protected readonly sidebarSections = computed<SidebarSection[]>(() => {
1496→    const c = this.store.content();
1497→    return [
1498→      { id: 'roles', label: 'Roles', count: (c.roles ?? []).length },
1499→      { id: 'events', label: 'Events', count: c.events.length },
1500→      { id: 'issues', label: 'Issues', count: c.issues.length },
1501→      { id: 'decisions', label: 'Decisions', count: c.decision_templates.length },
1502→      { id: 'turns', label: 'Turns', count: (c.turns ?? []).length },
1503→      { id: 'settings', label: 'Settings', count: 0 },
1504→    ];
1505→  });
1506→
1507→  ngOnInit(): void {
1508→    this.loadList();
1509→  }
1510→
1511→  private loadList(): void {
1512→    this.api.list().subscribe({
1513→      next: (list) => this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
1514→    });
1515→  }
1516→
1517→  protected loadScenario(id: number): void {
1518→    this.api.get(id).subscribe({
1519→      next: (s) => this.store.loadScenario(s.id, s.title, s.description, s.content),
1520→    });
1521→  }
