1523→  protected save(): void {
1524→    this.store.clearError();
1525→    const content = this.store.content();
1526→    const errors = validateScenarioContent(content);
1527→    if (!this.store.title().trim()) errors.unshift("Title is required.");
1528→    if (errors.length > 0) {
1529→      this.store.setError(errors.join("\n"));
1530→      return;
1531→    }
1532→    this.store.setSaving(true);
1533→    const payload = { title: this.store.title(), description: this.store.description(), content };
1534→    const id = this.store.scenarioId();
1535→    const req = id ? this.api.update(id, payload) : this.api.create(payload);
1536→    req.subscribe({
1537→      next: (s) => {
1538→        this.store.loadScenario(s.id, s.title, s.description, s.content);
1539→        this.store.setSaving(false);
1540→        this.loadList();
1541→      },
1542→      error: () => this.store.setError("Save failed — server rejected the scenario."),
1543→    });
1544→  }
1545→
1546→  protected saveAsCopy(): void {
1547→    const id = this.store.scenarioId();
1548→    if (!id) return;
1549→    this.store.setSaving(true);
1550→    this.api.clone(id).subscribe({
1551→      next: (s) => {
1552→        this.store.loadScenario(s.id, s.title, s.description, s.content);
1553→        this.store.setSaving(false);
1554→        this.loadList();
1555→      },
1556→      error: () => {
1557→        this.store.setSaving(false);
1558→        this.store.setError("Clone failed.");
1559→      },
1560→    });
1561→  }
1562→
1563→  protected deleteScenario(id: number): void {
1564→    this.api.delete(id).subscribe({ next: () => this.loadList() });
1565→  }
