from fastapi import HTTPException, status

from features.scenario.scenario_model import Scenario
from features.scenario.scenario_repository import ScenarioRepository
from features.scenario.scenario_schema import (
    CreateScenarioRequest,
    ScenarioResponse,
    UpdateScenarioRequest,
)


class ScenarioService:
    def __init__(self, repository: ScenarioRepository) -> None:
        self.repository = repository

    async def create_scenario(
        self,
        request: CreateScenarioRequest,
    ) -> ScenarioResponse:
        scenario = Scenario(
            title=request.title,
            description=request.description,
            domain_id=request.domain_id,
            content=request.content.model_dump(),
            version=request.version,
        )
        created = await self.repository.create(scenario)
        return ScenarioResponse.model_validate(created)

    async def get_scenario(self, scenario_id: int) -> ScenarioResponse:
        scenario = await self.repository.get_by_id(scenario_id)
        if not scenario:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Scenario not found",
            )
        return ScenarioResponse.model_validate(scenario)

    async def list_scenarios(
        self,
        domain_id: int | None = None,
    ) -> list[ScenarioResponse]:
        if domain_id is not None:
            scenarios = await self.repository.list_by_domain(domain_id)
        else:
            scenarios = await self.repository.list()
        return [ScenarioResponse.model_validate(s) for s in scenarios]

    async def update_scenario(
        self,
        scenario_id: int,
        request: UpdateScenarioRequest,
    ) -> ScenarioResponse:
        scenario = await self.repository.get_by_id(scenario_id)
        if not scenario:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Scenario not found",
            )

        update_data = request.model_dump(exclude_unset=True)
        for field, value in update_data.items():
            setattr(scenario, field, value)

        updated = await self.repository.update(scenario)
        return ScenarioResponse.model_validate(updated)

    async def delete_scenario(self, scenario_id: int) -> None:
        deleted = await self.repository.delete(scenario_id)
        if not deleted:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="Scenario not found",
            )

from fastapi import APIRouter, Depends, status

from core.dependencies import get_scenario_service
from features.scenario.scenario_schema import (
    CreateScenarioRequest,
    ScenarioResponse,
    UpdateScenarioRequest,
)
from features.scenario.scenario_service import ScenarioService

router = APIRouter(prefix="/api/scenarios", tags=["scenarios"])


@router.post(
    "",
    status_code=status.HTTP_201_CREATED,
    response_model=ScenarioResponse,
    operation_id="createScenario",
)
async def create_scenario(
    request: CreateScenarioRequest,
    service: ScenarioService = Depends(get_scenario_service),
) -> ScenarioResponse:
    return await service.create_scenario(request)


@router.get(
    "",
    response_model=list[ScenarioResponse],
    operation_id="listScenarios",
)
async def list_scenarios(
    domain_id: int | None = None,
    service: ScenarioService = Depends(get_scenario_service),
) -> list[ScenarioResponse]:
    return await service.list_scenarios(domain_id)


@router.get(
    "/{scenario_id}",
    response_model=ScenarioResponse,
    operation_id="getScenario",
)
async def get_scenario(
    scenario_id: int,
    service: ScenarioService = Depends(get_scenario_service),
) -> ScenarioResponse:
    return await service.get_scenario(scenario_id)


@router.put(
    "/{scenario_id}",
    response_model=ScenarioResponse,
    operation_id="updateScenario",
)
async def update_scenario(
    scenario_id: int,
    request: UpdateScenarioRequest,
    service: ScenarioService = Depends(get_scenario_service),
) -> ScenarioResponse:
    return await service.update_scenario(scenario_id, request)


@router.delete(
    "/{scenario_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    operation_id="deleteScenario",
)
async def delete_scenario(
    scenario_id: int,
    service: ScenarioService = Depends(get_scenario_service),
) -> None:
    await service.delete_scenario(scenario_id)

